-control" name="reviews[__INDEX__][country]" placeholder="Country"></div><div class="col-md-1"><input class="form-control" type="number" min="1" max="5" name="reviews[__INDEX__][rating]" value="5"></div><div class="col-md-4"><textarea class="form-control" name="reviews[__INDEX__][review]" placeholder="Review"></textarea></div><div class="col-md-2"><input class="form-control" type="file" name="reviews[__INDEX__][customer_image]"></div><div class="col-md-2"><input class="form-control" type="number" name="reviews[__INDEX__][display_order]" value="0"></div><div class="col-md-3"><input type="hidden" name="reviews[__INDEX__][is_approved]" value="0"><label><input type="checkbox" name="reviews[__INDEX__][is_approved]" value="1"> Approved</label></div><div class="col-md-2"><button class="btn btn-outline-danger" type="button" data-remove-new-row>Remove</button></div></div></div></template>
